const brain=[['identidade','orbit','Identidade empresarial','Essência, posicionamento e linguagem da empresa.','EMPRESA · V1.0'],['manual-medico','book','Manual da Consultora de Médicos','Abordagem, parceria e continuidade da jornada médica.','MANUAL · V1.2'],['manual-paciente','book','Manual da Consultora de Pacientes','Acolhimento, documentação e acompanhamento.','MANUAL · V1.1'],['manual-equipe','people','Manual da equipe','Responsabilidades, rotinas e participação humana.','MANUAL · V1.0'],['conhecimento','brain','Conhecimento científico','Referências e fontes para informação contextualizada.','BASE MINERVA'],['juridico','shield','Conhecimento jurídico','Regulação e referências aplicáveis à operação.','BASE MINERVA'],['memoria','layers','Histórico de relações','Eventos autorizados para acompanhamento humano.','OPERAÇÃO'],['decisoes','check','Decisões e versões','Propostas, versões e evidências para aprimorar.','GOVERNANÇA'],['fontes','file','Fontes e documentos','Originais preservados e materiais de referência.','BIBLIOTECA']];
