let saved={};try{saved=JSON.parse(localStorage.getItem('minerva-aurora-demo')||'{}')}catch{};const tasks=saved.tasks||[{title:'Preparar reunião com Dra. Juliana',stage:'A fazer',owner:'AS'},{title:'Revisar estratégia do próximo ciclo',stage:'Em andamento',owner:'AC'},{title:'Conferir preparação · pedido #1043',stage:'A fazer',owner:'DS'},{title:'Organizar materiais de onboarding',stage:'Em revisão',owner:'AS'},{title:'Preparar visita · Dr. Carlos',stage:'Concluído',owner:'BC'}];
